type Preferences = { notificationsEnabled: boolean }

// Stored on globalThis so the value survives dev-server module reloads.
// Swap these for real database calls in production.
const globalStore = globalThis as typeof globalThis & { __preferences?: Preferences }

function getStore(): Preferences {
  globalStore.__preferences ??= { notificationsEnabled: false }
  return globalStore.__preferences
}

export async function getNotificationPreference(): Promise<boolean> {
  return getStore().notificationsEnabled
}

export async function setNotificationPreference(enabled: boolean): Promise<void> {
  getStore().notificationsEnabled = enabled
}

