import { toggleNotifications } from './actions'
import { getNotificationPreference } from '@/lib/preferences'

// The preference lives outside the static render, so opt this page into
// dynamic rendering — refresh() re-renders it with the latest value.
export const dynamic = 'force-dynamic'

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{notificationsEnabled ? 'on' : 'off'}</strong>
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {notificationsEnabled ? 'off' : 'on'}
        </button>
      </form>
    </main>
  )
}

